#!/bin/bash
# experiment 010 — full sweep orchestrator for Qwen3.8-27B on a 16 GiB GPU.
#
# Runs every FEASIBLE (quant x KV-type x context) cell. The cell list is
# generated by scripts/budget.py --plan, which guarantees each cell fits the
# VRAM budget — so this script never attempts an OOM config.
#
#   MODE=perf  -> real-prompt decode/prefill via perf-probe.py   (default)
#   MODE=agent -> HermesBench hermes-core task-completion per cell
#
# Prereqs: configs/vast-build.sh (llama-server on PATH), download-verify.sh
#          (models + results/models/manifest.json), and (for agent mode)
#          HermesBench + `hermes` CLI.

set -u
REPO="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
EXP="$REPO/experiments/010-qwen38-27b-16gb-sweep"
MODE="${MODE:-perf}"
MODELS_DIR="${MODELS_DIR:-$EXP/results/models}"
MANIFEST="$MODELS_DIR/manifest.json"
PORT=1235
: "${LLAMA_SERVER:=llama-server}"

if [ ! -f "$MANIFEST" ]; then
  echo "ERROR: $MANIFEST missing. Run scripts/download-verify.sh first." >&2
  exit 1
fi

mapfile -t CELLS < <(python3 "$EXP/scripts/budget.py" --plan)
echo "sweep: ${#CELLS[@]} feasible cells (mode=$MODE)"

for cell in "${CELLS[@]}"; do
  STEM="$(echo "$cell" | cut -f1)"
  KV="$(echo "$cell"   | cut -f2)"
  CTX="$(echo "$cell"   | cut -f3)"
  MODEL_PATH="$(python3 -c "import json;print(json.load(open('$MANIFEST'))['$STEM'])")"
  if [ ! -f "$MODEL_PATH" ]; then
    echo "SKIP $STEM: model not found at $MODEL_PATH"
    continue
  fi
  OUT="$EXP/results/$STEM/$KV/$CTX"; mkdir -p "$OUT"
  echo "=== $STEM kv=$KV ctx=$CTX ==="

  CTK=""; CTV=""
  if [ "$KV" != "native" ]; then CTK="$KV"; CTV="$KV"; fi

  MODEL_PATH="$MODEL_PATH" PORT="$PORT" CTX="$CTX" CTK="$CTK" CTV="$CTV" \
    LLAMA_SERVER="$LLAMA_SERVER" bash "$EXP/configs/llama-server-sweep.sh" &
  SRV=$!

  # Capture peak VRAM for this cell (nvidia-smi on the Vast box).
  VRAM_PID=""; VRAM_LOG="$OUT/vram.csv"
  if command -v nvidia-smi >/dev/null 2>&1; then
    ( while kill -0 "$SRV" 2>/dev/null; do
        nvidia-smi --query-gpu=memory.used --format=csv,noheader,nounits \
          >> "$VRAM_LOG"; sleep 2
      done ) & VRAM_PID=$!
  fi

  for i in $(seq 1 60); do
    curl -s "http://127.0.0.1:$PORT/health" >/dev/null 2>&1 && break
    sleep 3
  done

  if [ "$MODE" = "perf" ]; then
    python3 "$EXP/scripts/perf-probe.py" \
      --url "http://127.0.0.1:$PORT" --output "$OUT/perf.json" --repeats 3
  else
    hermes config set providers.qwen38-local.api "http://127.0.0.1:$PORT/v1"
    hermes config set providers.qwen38-local.context_length "$CTX"
    hermesbench run --provider qwen38-local --model qwen3.8-27b \
      --suite hermes-core --model-size 27e9 | tee "$OUT/hermesbench.log"
  fi

  kill "$SRV" 2>/dev/null; wait "$SRV" 2>/dev/null
  [ -n "$VRAM_PID" ] && kill "$VRAM_PID" 2>/dev/null
done
echo "sweep done -> $EXP/results"
